const dueRows = $('Get Due Follow-Ups').all().map((item) => item.json);
const newRows = $('Get High-Score Leads').all().map((item) => item.json);

const formatMoney = (val) => {
  const num = Number(val);
  if (!Number.isFinite(num) || num <= 0) return null;
  return '$' + Math.round(num).toLocaleString('en-US');
};

const formatFriction = (tags) => {
  if (!tags) return '';
  if (Array.isArray(tags)) return tags.slice(0, 3).join(', ');
  return String(tags);
};

const formatDueLine = (row, idx) => {
  const acqBadge = row.is_acquisition ? ' [ACQ]' : '';
  const loc = [row.borr_city, row.borr_state].filter(Boolean).join(', ');
  const contact = [row.best_phone, row.best_email].filter(Boolean).join(' | ') || 'No direct contact yet';
  const lastOut = row.latest_outcome ? `Last: ${row.latest_outcome}` : `Touches: ${row.total_touches ?? 0}`;
  return `${idx + 1}. *${row.borr_name}*${acqBadge} (${loc || 'N/A'}) — Score *${row.computed_lead_score}* | ${lastOut}\n    ${contact}`;
};

const formatNewLine = (row, idx) => {
  const acqBadge = row.is_acquisition ? ' [ACQ]' : '';
  const loc = [row.borr_city, row.borr_state].filter(Boolean).join(', ');
  const loan = formatMoney(row.gross_approval);
  const meta = [loc, loan ? `Loan ${loan}` : null, row.campaign_track || null].filter(Boolean).join(' • ');
  const contact = [row.best_phone, row.best_email].filter(Boolean).join(' | ') || 'No direct contact yet';
  const friction = formatFriction(row.friction_tags);
  return `${idx + 1}. *${row.borr_name}*${acqBadge} — Score *${row.computed_lead_score}* (${meta})\n    ${contact}${friction ? `\n    Signals: ${friction}` : ''}`;
};

const todayLabel = new Intl.DateTimeFormat('en-US', {
  timeZone: 'America/New_York',
  weekday: 'short',
  month: 'short',
  day: 'numeric',
}).format(new Date());

const dueSectionText =
  dueRows.length > 0
    ? dueRows.map(formatDueLine).join('\n')
    : '_No follow-up nudges due today._';

const newSectionText =
  newRows.length > 0
    ? newRows.map(formatNewLine).join('\n')
    : '_No uncontacted high-score leads (60+) in queue._';

const fallbackText = `SBA Morning Queue (${todayLabel}) — Due Follow-Ups: ${dueRows.length} | High-Score New: ${newRows.length}`;

const blocks = [
  {
    type: 'header',
    text: {
      type: 'plain_text',
      text: `SBA Outbound Queue • ${todayLabel}`,
      emoji: false
    }
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*Due Follow-Up Nudges (${dueRows.length})*\n${dueSectionText}`
    }
  },
  { type: 'divider' },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*Uncontacted High-Score Leads — 60+ (${newRows.length})*\n${newSectionText}`
    }
  }
];

return [
  {
    json: {
      text: fallbackText,
      blocks,
      due_count: dueRows.length,
      new_count: newRows.length
    }
  }
];
